INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000780', 'Rumus volumetrik OOIP (original oil in place) memuat faktor konversi acre-ft ke barrel sebesar...', 'The volumetric OOIP (original oil in place) formula includes the acre-ft to barrel conversion factor of...', 'option', 'PFC000000007', 'Inisialisasi', 'a:4:{i:0;s:5:"7.758";i:1;s:5:"775,8";i:2;s:9:"7.758.000";i:3;s:5:"1.000";}', 'a:4:{i:0;s:5:"7,758";i:1;s:5:"775.8";i:2;s:9:"7,758,000";i:3;s:5:"1,000";}', '', '7.758', '7,758', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000781', 'Net-to-gross ratio (NTG) adalah perbandingan antara...', 'The net-to-gross ratio (NTG) is the ratio between...', 'option', 'PFC000000007', 'Inisialisasi', 'a:4:{i:0;s:27:"Porositas dan permeabilitas";i:1;s:45:"Ketebalan net pay dan ketebalan total formasi";i:2;s:32:"Saturasi minyak dan saturasi air";i:3;s:37:"Volume reservoir dan volume permukaan";}', 'a:4:{i:0;s:25:"Porosity and permeability";i:1;s:47:"Net pay thickness and total formation thickness";i:2;s:35:"Oil saturation and water saturation";i:3;s:35:"Reservoir volume and surface volume";}', '', 'Ketebalan net pay dan ketebalan total formasi', 'Net pay thickness and total formation thickness', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000782', 'Recovery factor (RF) menyatakan...', 'The recovery factor (RF) expresses...', 'option', 'PFC000000007', 'Inisialisasi', 'a:4:{i:0;s:36:"Perbandingan OOIP terhadap luas area";i:1;s:47:"Perbandingan cadangan terproduksi terhadap OOIP";i:2;s:35:"Perbandingan porositas dan saturasi";i:3;s:35:"Perbandingan tekanan awal dan akhir";}', 'a:4:{i:0;s:33:"The ratio of OOIP to areal extent";i:1;s:41:"The ratio of recoverable reserves to OOIP";i:2;s:35:"The ratio of porosity to saturation";i:3;s:39:"The ratio of initial and final pressure";}', '', 'Perbandingan cadangan terproduksi terhadap OOIP', 'The ratio of recoverable reserves to OOIP', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000783', 'OOIP adalah singkatan dari...', 'OOIP stands for...', 'option', 'PFC000000007', 'Inisialisasi', 'a:4:{i:0;s:27:"Operating Oil Index Program";i:1;s:31:"Overburden Oil Initial Pressure";i:2;s:29:"Oil Output Injection Pressure";i:3;s:21:"Original Oil In Place";}', 'a:4:{i:0;s:27:"Operating Oil Index Program";i:1;s:31:"Overburden Oil Initial Pressure";i:2;s:29:"Oil Output Injection Pressure";i:3;s:21:"Original Oil In Place";}', '', 'Original Oil In Place', 'Original Oil In Place', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000784', 'Metode volumetrik digunakan untuk...', 'The volumetric method is used to...', 'option', 'PFC000000007', 'Inisialisasi', 'a:4:{i:0;s:29:"Mengukur laju produksi harian";i:1;s:20:"Menentukan harga gas";i:2;s:27:"Menghitung biaya pengeboran";i:3;s:62:"Menghitung volume hidrokarbon dari parameter batuan dan fluida";}', 'a:4:{i:0;s:29:"Measure daily production rate";i:1;s:20:"Determine gas prices";i:2;s:24:"Calculate drilling costs";i:3;s:59:"Calculate hydrocarbon volume from rock and fluid parameters";}', '', 'Menghitung volume hidrokarbon dari parameter batuan dan fluida', 'Calculate hydrocarbon volume from rock and fluid parameters', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000785', 'Dalam estimasi cadangan probabilistik, P90 berarti...', 'In probabilistic reserves estimation, P90 means...', 'option', 'PFC000000007', 'Inisialisasi', 'a:4:{i:0;s:29:"Nilai dengan probabilitas 10%";i:1;s:22:"Nilai maksimum absolut";i:2;s:75:"Nilai dengan probabilitas 90% volume aktual lebih besar dari nilai tersebut";i:3;s:15:"Nilai rata-rata";}', 'a:4:{i:0;s:32:"The value with a 10% probability";i:1;s:26:"The absolute maximum value";i:2;s:62:"The value with a 90% probability that actual volume is greater";i:3;s:17:"The average value";}', '', 'Nilai dengan probabilitas 90% volume aktual lebih besar dari nilai tersebut', 'The value with a 90% probability that actual volume is greater', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000786', 'Saturasi hidrokarbon (So) dihitung dari...', 'Hydrocarbon saturation (So) is calculated from...', 'option', 'PFC000000007', 'Inisialisasi', 'a:4:{i:0;s:6:"1 + Sw";i:1;s:6:"1 - Sw";i:2;s:8:"Sw / phi";i:3;s:8:"phi / Sw";}', 'a:4:{i:0;s:6:"1 + Sw";i:1;s:6:"1 - Sw";i:2;s:8:"Sw / phi";i:3;s:8:"phi / Sw";}', '', '1 - Sw', '1 - Sw', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000787', 'Manakah parameter yang dibutuhkan dalam perhitungan volumetrik OOIP?', 'Which parameters are required in the volumetric OOIP calculation?', 'multi', 'PFC000000007', 'Inisialisasi', 'a:4:{i:0;s:29:"Porositas dan saturasi minyak";i:1;s:26:"Faktor volume formasi (Bo)";i:2;s:9:"Luas area";i:3;s:17:"Ketebalan net pay";}', 'a:4:{i:0;s:27:"Porosity and oil saturation";i:1;s:28:"Formation volume factor (Bo)";i:2;s:12:"Areal extent";i:3;s:17:"Net pay thickness";}', '', 'a:4:{i:0;s:9:"Luas area";i:1;s:17:"Ketebalan net pay";i:2;s:29:"Porositas dan saturasi minyak";i:3;s:26:"Faktor volume formasi (Bo)";}', 'a:4:{i:0;s:12:"Areal extent";i:1;s:17:"Net pay thickness";i:2;s:27:"Porosity and oil saturation";i:3;s:28:"Formation volume factor (Bo)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000788', 'Urutkan alur estimasi volume hidrokarbon secara volumetrik.', 'Arrange the volumetric hydrocarbon volume estimation workflow.', 'drag', 'PFC000000007', 'Inisialisasi', 'a:6:{i:0;s:35:"Menentukan batas area dan ketebalan";i:1;s:30:"Menghitung porositas rata-rata";i:2;s:31:"Menghitung saturasi hidrokarbon";i:3;s:23:"Perhitungan NPV dan IRR";i:4;s:21:"Menentukan NTG dan Bo";i:5;s:15:"Menghitung OOIP";}', 'a:6:{i:0;s:41:"Determine the area boundary and thickness";i:1;s:26:"Calculate average porosity";i:2;s:32:"Calculate hydrocarbon saturation";i:3;s:23:"NPV and IRR calculation";i:4;s:20:"Determine NTG and Bo";i:5;s:14:"Calculate OOIP";}', '', 'a:5:{i:0;s:35:"Menentukan batas area dan ketebalan";i:1;s:30:"Menghitung porositas rata-rata";i:2;s:31:"Menghitung saturasi hidrokarbon";i:3;s:21:"Menentukan NTG dan Bo";i:4;s:15:"Menghitung OOIP";}', 'a:5:{i:0;s:41:"Determine the area boundary and thickness";i:1;s:26:"Calculate average porosity";i:2;s:32:"Calculate hydrocarbon saturation";i:3;s:20:"Determine NTG and Bo";i:4;s:14:"Calculate OOIP";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000789', 'Benarkah cadangan (reserves) selalu lebih kecil atau sama dengan OOIP?', 'Is it true that reserves are always less than or equal to OOIP?', 'yesorno', 'PFC000000007', 'Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000790', 'Diketahui A = 1000 acre, h = 20 ft, phi = 0,2, So = 0,7, dan Bo = 1,2 RB/STB. Berapa OOIP-nya?', 'Given A = 1000 acres, h = 20 ft, phi = 0.2, So = 0.7, and Bo = 1.2 RB/STB. What is the OOIP?', 'option', 'PFC000000007', 'Final Advanced', 'a:4:{i:0;s:9:"1,8 MMSTB";i:1;s:10:"18,1 MMSTB";i:2;s:9:"181 MMSTB";i:3;s:9:"2,2 MMSTB";}', 'a:4:{i:0;s:9:"1.8 MMSTB";i:1;s:10:"18.1 MMSTB";i:2;s:9:"181 MMSTB";i:3;s:9:"2.2 MMSTB";}', '', '18,1 MMSTB', '18.1 MMSTB', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000791', 'Diketahui A = 640 acre, h = 30 ft, phi = 0,18, Sw = 0,30, dan Bg = 0,005 ft3/SCF. Berapa OGIP-nya?', 'Given A = 640 acres, h = 30 ft, phi = 0.18, Sw = 0.30, and Bg = 0.005 ft3/SCF. What is the OGIP?', 'option', 'PFC000000007', 'Final Advanced', 'a:4:{i:0;s:8:"2,1 BSCF";i:1;s:9:"21,1 BSCF";i:2;s:8:"211 BSCF";i:3;s:9:"1,05 BSCF";}', 'a:4:{i:0;s:8:"2.1 BSCF";i:1;s:9:"21.1 BSCF";i:2;s:8:"211 BSCF";i:3;s:9:"1.05 BSCF";}', '', '21,1 BSCF', '21.1 BSCF', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000792', 'Recovery factor pada reservoir dengan water drive yang kuat umumnya...', 'The recovery factor in a reservoir with strong water drive is generally...', 'option', 'PFC000000007', 'Final Advanced', 'a:4:{i:0;s:41:"Lebih rendah dibanding solution gas drive";i:1;s:41:"Lebih tinggi dibanding solution gas drive";i:2;s:15:"Sama dengan nol";i:3;s:33:"Tidak dipengaruhi mekanisme drive";}', 'a:4:{i:0;s:29:"Lower than solution gas drive";i:1;s:30:"Higher than solution gas drive";i:2;s:13:"Equal to zero";i:3;s:35:"Not affected by the drive mechanism";}', '', 'Lebih tinggi dibanding solution gas drive', 'Higher than solution gas drive', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000793', 'Penerapan cutoff yang terlalu ketat pada perhitungan net pay akan menyebabkan...', 'Applying cutoffs that are too strict in net pay calculation will cause...', 'option', 'PFC000000007', 'Final Advanced', 'a:4:{i:0;s:40:"OOIP menjadi lebih kecil (underestimate)";i:1;s:39:"OOIP menjadi lebih besar (overestimate)";i:2;s:18:"OOIP tidak berubah";i:3;s:25:"Porositas menjadi negatif";}', 'a:4:{i:0;s:38:"OOIP to become smaller (underestimate)";i:1;s:36:"OOIP to become larger (overestimate)";i:2;s:24:"OOIP to remain unchanged";i:3;s:27:"Porosity to become negative";}', '', 'OOIP menjadi lebih kecil (underestimate)', 'OOIP to become smaller (underestimate)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000794', 'Klasifikasi cadangan 2P terdiri dari...', 'The 2P reserves classification consists of...', 'option', 'PFC000000007', 'Final Advanced', 'a:4:{i:0;s:17:"Proven + Probable";i:1;s:17:"Proven + Possible";i:2;s:19:"Probable + Possible";i:3;s:11:"Proven saja";}', 'a:4:{i:0;s:17:"Proven + Probable";i:1;s:17:"Proven + Possible";i:2;s:19:"Probable + Possible";i:3;s:11:"Proven only";}', '', 'Proven + Probable', 'Proven + Probable', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000795', 'Metode Monte Carlo dalam estimasi volume digunakan untuk...', 'The Monte Carlo method in volume estimation is used to...', 'option', 'PFC000000007', 'Final Advanced', 'a:4:{i:0;s:26:"Menentukan kedalaman sumur";i:1;s:26:"Menghitung laju alir sumur";i:2;s:26:"Mengukur viskositas minyak";i:3;s:68:"Menggabungkan ketidakpastian beberapa parameter secara probabilistik";}', 'a:4:{i:0;s:20:"Determine well depth";i:1;s:24:"Calculate well flow rate";i:2;s:21:"Measure oil viscosity";i:3;s:63:"Combine the uncertainty of several parameters probabilistically";}', '', 'Menggabungkan ketidakpastian beberapa parameter secara probabilistik', 'Combine the uncertainty of several parameters probabilistically', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000796', 'Perbedaan hasil antara perhitungan volumetrik dan material balance umumnya menunjukkan...', 'A difference between volumetric and material balance results generally indicates...', 'option', 'PFC000000007', 'Final Advanced', 'a:4:{i:0;s:23:"Perhitungan pasti benar";i:1;s:76:"Perlu evaluasi ulang data (misalnya tekanan, geologi, atau parameter batuan)";i:2;s:36:"Reservoir tidak memiliki hidrokarbon";i:3;s:17:"Tidak ada artinya";}', 'a:4:{i:0;s:37:"The calculation is definitely correct";i:1;s:76:"A need to re-evaluate the data (e.g., pressure, geology, or rock parameters)";i:2;s:33:"The reservoir has no hydrocarbons";i:3;s:18:"Nothing meaningful";}', '', 'Perlu evaluasi ulang data (misalnya tekanan, geologi, atau parameter batuan)', 'A need to re-evaluate the data (e.g., pressure, geology, or rock parameters)', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000797', 'Upscaling parameter petrofisika dari core ke skala reservoir bertujuan untuk...', 'Upscaling petrophysical parameters from core to reservoir scale aims to...', 'option', 'PFC000000007', 'Final Advanced', 'a:4:{i:0;s:23:"Menghilangkan data core";i:1;s:55:"Memperoleh nilai representatif untuk simulasi reservoir";i:2;s:23:"Menentukan harga minyak";i:3;s:23:"Mengurangi jumlah sumur";}', 'a:4:{i:0;s:19:"Eliminate core data";i:1;s:53:"Obtain representative values for reservoir simulation";i:2;s:20:"Determine oil prices";i:3;s:26:"Reduce the number of wells";}', '', 'Memperoleh nilai representatif untuk simulasi reservoir', 'Obtain representative values for reservoir simulation', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000798', 'Parameter yang paling sensitif mempengaruhi hasil OOIP pada rumus volumetrik adalah...', 'The parameter that most sensitively affects the OOIP result in the volumetric formula is...', 'option', 'PFC000000007', 'Final Advanced', 'a:4:{i:0;s:23:"Jenis lumpur pengeboran";i:1;s:12:"Warna batuan";i:2;s:15:"Kedalaman sumur";i:3;s:45:"Porositas, saturasi, ketebalan, dan luas area";}', 'a:4:{i:0;s:17:"Drilling mud type";i:1;s:10:"Rock color";i:2;s:10:"Well depth";i:3;s:49:"Porosity, saturation, thickness, and areal extent";}', '', 'Porositas, saturasi, ketebalan, dan luas area', 'Porosity, saturation, thickness, and areal extent', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000799', 'Saturasi air yang digunakan untuk perhitungan volumetrik sebaiknya berasal dari...', 'The water saturation used for volumetric calculation should come from...', 'option', 'PFC000000007', 'Final Advanced', 'a:4:{i:0;s:38:"Data dari sumur tetangga tanpa koreksi";i:1;s:10:"Asumsi 50%";i:2;s:62:"Data log yang dikalibrasi dengan core dan data tekanan kapiler";i:3;s:12:"Warna batuan";}', 'a:4:{i:0;s:40:"Neighboring well data without correction";i:1;s:16:"A 50% assumption";i:2;s:57:"Log data calibrated with core and capillary pressure data";i:3;s:10:"Rock color";}', '', 'Data log yang dikalibrasi dengan core dan data tekanan kapiler', 'Log data calibrated with core and capillary pressure data', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000800', 'Sweep efficiency memengaruhi...', 'Sweep efficiency affects...', 'option', 'PFC000000007', 'Final Advanced', 'a:4:{i:0;s:22:"Porositas total batuan";i:1;s:69:"Fraksi volume reservoir yang benar-benar tersapu oleh fluida pendesak";i:2;s:16:"Densitas matriks";i:3;s:15:"Kedalaman sumur";}', 'a:4:{i:0;s:19:"Total rock porosity";i:1;s:71:"The fraction of reservoir volume actually swept by the displacing fluid";i:2;s:14:"Matrix density";i:3;s:10:"Well depth";}', '', 'Fraksi volume reservoir yang benar-benar tersapu oleh fluida pendesak', 'The fraction of reservoir volume actually swept by the displacing fluid', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000801', 'Estimated Ultimate Recovery (EUR) adalah...', 'Estimated Ultimate Recovery (EUR) is...', 'option', 'PFC000000007', 'Final Advanced', 'a:4:{i:0;s:11:"Volume OOIP";i:1;s:24:"Produksi harian saat ini";i:2;s:28:"Jumlah sumur yang akan dibor";i:3;s:68:"Total perkiraan produksi kumulatif sampai akhir umur sumur/reservoir";}', 'a:4:{i:0;s:11:"OOIP volume";i:1;s:24:"Current daily production";i:2;s:33:"The number of wells to be drilled";i:3;s:82:"The total estimated cumulative production until the end of the well/reservoir life";}', '', 'Total perkiraan produksi kumulatif sampai akhir umur sumur/reservoir', 'The total estimated cumulative production until the end of the well/reservoir life', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000802', 'Manakah penyebab perbedaan antara OOIP volumetrik dan hasil material balance?', 'Which are causes of differences between volumetric OOIP and material balance results?', 'multi', 'PFC000000007', 'Final Advanced', 'a:4:{i:0;s:33:"Ketidakpastian geometri reservoir";i:1;s:31:"Data tekanan yang kurang akurat";i:2;s:25:"Warna minyak yang berbeda";i:3;s:41:"Parameter batuan yang tidak representatif";}', 'a:4:{i:0;s:28:"Uncertain reservoir geometry";i:1;s:24:"Inaccurate pressure data";i:2;s:19:"Different oil color";i:3;s:34:"Non-representative rock parameters";}', '', 'a:3:{i:0;s:31:"Data tekanan yang kurang akurat";i:1;s:33:"Ketidakpastian geometri reservoir";i:2;s:41:"Parameter batuan yang tidak representatif";}', 'a:3:{i:0;s:24:"Inaccurate pressure data";i:1;s:28:"Uncertain reservoir geometry";i:2;s:34:"Non-representative rock parameters";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000803', 'Manakah yang termasuk sumber ketidakpastian dalam estimasi cadangan?', 'Which of the following are sources of uncertainty in reserves estimation?', 'multi', 'PFC000000007', 'Final Advanced', 'a:4:{i:0;s:33:"Kontak fluida dan batas reservoir";i:1;s:38:"Distribusi porositas dan permeabilitas";i:2;s:26:"Kualitas data log dan core";i:3;s:21:"Jumlah pekerja di rig";}', 'a:4:{i:0;s:39:"Fluid contacts and reservoir boundaries";i:1;s:38:"Porosity and permeability distribution";i:2;s:25:"Log and core data quality";i:3;s:28:"Number of workers on the rig";}', '', 'a:3:{i:0;s:38:"Distribusi porositas dan permeabilitas";i:1;s:33:"Kontak fluida dan batas reservoir";i:2;s:26:"Kualitas data log dan core";}', 'a:3:{i:0;s:38:"Porosity and permeability distribution";i:1;s:39:"Fluid contacts and reservoir boundaries";i:2;s:25:"Log and core data quality";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000804', 'Manakah yang perlu dilaporkan bersama hasil estimasi volume?', 'Which of the following should be reported along with the volume estimate?', 'multi', 'PFC000000007', 'Final Advanced', 'a:4:{i:0;s:36:"Rentang ketidakpastian (P90/P50/P10)";i:1;s:18:"Metode perhitungan";i:2;s:20:"Warna peta reservoir";i:3;s:33:"Asumsi dan parameter yang dipakai";}', 'a:4:{i:0;s:31:"Uncertainty range (P90/P50/P10)";i:1;s:18:"Calculation method";i:2;s:19:"Reservoir map color";i:3;s:31:"Assumptions and parameters used";}', '', 'a:3:{i:0;s:33:"Asumsi dan parameter yang dipakai";i:1;s:36:"Rentang ketidakpastian (P90/P50/P10)";i:2;s:18:"Metode perhitungan";}', 'a:3:{i:0;s:31:"Assumptions and parameters used";i:1;s:31:"Uncertainty range (P90/P50/P10)";i:2;s:18:"Calculation method";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000805', 'Manakah pernyataan yang benar tentang NTG?', 'Which statements about NTG are correct?', 'multi', 'PFC000000007', 'Final Advanced', 'a:4:{i:0;s:21:"NTG mempengaruhi OOIP";i:1;s:32:"NTG selalu sama dengan porositas";i:2;s:27:"NTG bernilai antara 0 dan 1";i:3;s:38:"NTG memperhitungkan zona non-produktif";}', 'a:4:{i:0;s:16:"NTG affects OOIP";i:1;s:31:"NTG is always equal to porosity";i:2;s:26:"NTG ranges between 0 and 1";i:3;s:37:"NTG accounts for non-productive zones";}', '', 'a:3:{i:0;s:27:"NTG bernilai antara 0 dan 1";i:1;s:38:"NTG memperhitungkan zona non-produktif";i:2;s:21:"NTG mempengaruhi OOIP";}', 'a:3:{i:0;s:26:"NTG ranges between 0 and 1";i:1;s:37:"NTG accounts for non-productive zones";i:2;s:16:"NTG affects OOIP";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000806', 'Urutkan klasifikasi cadangan dari tingkat keyakinan paling tinggi ke paling rendah.', 'Arrange reserves classifications from highest to lowest confidence level.', 'drag', 'PFC000000007', 'Final Advanced', 'a:4:{i:0;s:44:"Sumber daya kontingen (contingent resources)";i:1;s:11:"Proven (1P)";i:2;s:13:"Probable (2P)";i:3;s:13:"Possible (3P)";}', 'a:4:{i:0;s:20:"Contingent resources";i:1;s:11:"Proven (1P)";i:2;s:13:"Probable (2P)";i:3;s:13:"Possible (3P)";}', '', 'a:3:{i:0;s:11:"Proven (1P)";i:1;s:13:"Probable (2P)";i:2;s:13:"Possible (3P)";}', 'a:3:{i:0;s:11:"Proven (1P)";i:1;s:13:"Probable (2P)";i:2;s:13:"Possible (3P)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000807', 'Urutkan tahapan studi lapangan dari eksplorasi sampai estimasi cadangan.', 'Arrange the field study stages from exploration to reserves estimation.', 'drag', 'PFC000000007', 'Final Advanced', 'a:6:{i:0;s:31:"Eksplorasi dan pengumpulan data";i:1;s:32:"Penilaian formasi (log dan core)";i:2;s:33:"Pemodelan geologi dan petrofisika";i:3;s:22:"Perhitungan volumetrik";i:4;s:36:"Estimasi cadangan dan ketidakpastian";i:5;s:36:"Pembongkaran fasilitas (abandonment)";}', 'a:6:{i:0;s:32:"Exploration and data acquisition";i:1;s:37:"Formation evaluation (logs and cores)";i:2;s:37:"Geological and petrophysical modeling";i:3;s:22:"Volumetric calculation";i:4;s:35:"Reserves and uncertainty estimation";i:5;s:38:"Facility decommissioning (abandonment)";}', '', 'a:5:{i:0;s:31:"Eksplorasi dan pengumpulan data";i:1;s:32:"Penilaian formasi (log dan core)";i:2;s:33:"Pemodelan geologi dan petrofisika";i:3;s:22:"Perhitungan volumetrik";i:4;s:36:"Estimasi cadangan dan ketidakpastian";}', 'a:5:{i:0;s:32:"Exploration and data acquisition";i:1;s:37:"Formation evaluation (logs and cores)";i:2;s:37:"Geological and petrophysical modeling";i:3;s:22:"Volumetric calculation";i:4;s:35:"Reserves and uncertainty estimation";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000808', 'Benarkah nilai P10 selalu lebih besar dari P90 pada distribusi volume cadangan?', 'Is it true that the P10 value is always greater than P90 in a reserves volume distribution?', 'yesorno', 'PFC000000007', 'Final Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000809', 'Benarkah recovery factor dapat melebihi 100%?', 'Is it true that the recovery factor can exceed 100%?', 'yesorno', 'PFC000000007', 'Final Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
